diff --git a/packages/server/src/boards/file-board-store.test.ts b/packages/server/src/boards/file-board-store.test.ts
index 4af335b5..8bcdec5b 100644
--- a/packages/server/src/boards/file-board-store.test.ts
+++ b/packages/server/src/boards/file-board-store.test.ts
@@ -143,6 +143,25 @@ describe("FileBoardStore", () => {
       expect(next[0]?.seq).toBe(2);
     });

+    it("survives a crash interrupted mid-heal: stale temp file, log intact", async () => {
+      await store.createBoard("b1", SCHEMA);
+      await store.append("b1", [{ actor: "a", op: createOp("e1") }]);
+      // The state a crash between temp-write and rename leaves behind: the
+      // original log still carries its torn tail, and log.jsonl.heal exists.
+      await appendFile(logPath(), '{"end":3,"event":{"seq":2,"acto');
+      await writeFile(
+        join(root, Buffer.from("b1", "utf8").toString("base64url"), "log.jsonl.heal"),
+        "half-written heal",
+      );
+
+      const reopened = new FileBoardStore(root);
+      expect((await reopened.getEvents("b1", 0)).map((event) => event.seq)).toEqual([1]);
+      // Appending re-runs the heal (overwriting the stale temp) and continues seqs.
+      const next = await reopened.append("b1", [{ actor: "a", op: createOp("e2") }]);
+      expect(next[0]?.seq).toBe(2);
+      expect((await reopened.getEvents("b1", 0)).map((event) => event.seq)).toEqual([1, 2]);
+    });
+
     it("throws on mid-file corruption instead of returning a truncated log", async () => {
       await store.createBoard("b1", SCHEMA);
       await store.append("b1", [{ actor: "a", op: createOp("e1") }]);

diff --git a/packages/server/src/boards/file-board-store.ts b/packages/server/src/boards/file-board-store.ts
index 7c6e6453..acc6f849 100644
--- a/packages/server/src/boards/file-board-store.ts
+++ b/packages/server/src/boards/file-board-store.ts
@@ -1,4 +1,4 @@
-import { appendFile, mkdir, readFile, writeFile } from "node:fs/promises";
+import { appendFile, mkdir, readFile, rename, writeFile } from "node:fs/promises";
 import { join } from "node:path";
 import type { Event, WireSchema } from "@wboard/core";
 import type { AppendEntry, BoardStore } from "@wboard/server";
@@ -102,8 +102,14 @@ export class FileBoardStore implements BoardStore {
     const { events, recovered } = await this.#readLog(boardId);
     if (recovered) {
       // Heal before anything appends after the garbage tail. Serialized-write
-      // context only (append); reads never rewrite.
-      await writeFile(join(this.#dir(boardId), "log.jsonl"), logLines(events));
+      // context only (append); reads never rewrite. Temp-then-rename so the
+      // heal itself is crash-safe: an in-place writeFile truncates first, and
+      // a crash in that window would lose the whole log. A crash before the
+      // rename leaves log.jsonl untouched (recovery just re-runs); rename is
+      // atomic on the same filesystem.
+      const dir = this.#dir(boardId);
+      await writeFile(join(dir, "log.jsonl.heal"), logLines(events));
+      await rename(join(dir, "log.jsonl.heal"), join(dir, "log.jsonl"));
     }
     const last = events.at(-1)?.seq ?? 0;
     this.#tail.set(boardId, last);

